package postgres

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/manovaspace/orbit-auth/internal/domain"
	"github.com/manovaspace/orbit-auth/internal/infrastructure/postgres/sqlcgen"
)

// Store implements the domain stores on Postgres. Every statement it runs is
// generated by sqlc from queries/*.sql.
type Store struct {
	pool    *pgxpool.Pool
	queries *sqlcgen.Queries
}

// New builds the store on a pgx pool.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool, queries: sqlcgen.New(pool)}
}

// UpsertChallenge writes one challenge.
func (s *Store) UpsertChallenge(ctx context.Context, ch domain.OTPChallenge) error {
	id, err := uuid.Parse(ch.ID)
	if err != nil {
		return fmt.Errorf("postgres: challenge id %q: %w", ch.ID, err)
	}
	return s.queries.UpsertChallenge(ctx, sqlcgen.UpsertChallengeParams{
		ID:         id,
		Identifier: ch.Identifier,
		Channel:    ch.Channel,
		CodeHash:   ch.CodeHash,
		ExpiresAt:  timestamptz(ch.ExpiresAt),
	})
}

// GetLatestChallenge returns the newest challenge for identifier and channel.
func (s *Store) GetLatestChallenge(ctx context.Context, identifier, channel string) (domain.OTPChallenge, error) {
	row, err := s.queries.GetLatestChallenge(ctx, sqlcgen.GetLatestChallengeParams{
		Identifier: identifier,
		Channel:    channel,
	})
	if err != nil {
		return domain.OTPChallenge{}, err
	}
	return domain.OTPChallenge{
		ID:         row.ID,
		Identifier: row.Identifier,
		Channel:    row.Channel,
		CodeHash:   row.CodeHash,
		ExpiresAt:  row.ExpiresAt.Time,
		Attempts:   int(row.Attempts),
	}, nil
}

// IncrementAttempts adds one wrong attempt to a challenge.
func (s *Store) IncrementAttempts(ctx context.Context, id string) error {
	parsed, err := uuid.Parse(id)
	if err != nil {
		return fmt.Errorf("postgres: challenge id %q: %w", id, err)
	}
	return s.queries.IncrementChallengeAttempts(ctx, parsed)
}

// ConsumeChallenge deletes a used challenge.
func (s *Store) ConsumeChallenge(ctx context.Context, id string) error {
	parsed, err := uuid.Parse(id)
	if err != nil {
		return fmt.Errorf("postgres: challenge id %q: %w", id, err)
	}
	return s.queries.ConsumeChallenge(ctx, parsed)
}

// DeleteExpiredChallenges removes challenges past their expiry.
func (s *Store) DeleteExpiredChallenges(ctx context.Context) error {
	return s.queries.DeleteExpiredChallenges(ctx)
}

// FindOrCreateByEmail returns the user or creates an active user with email.
func (s *Store) FindOrCreateByEmail(ctx context.Context, email string) (domain.User, error) {
	user, err := s.findByEmail(ctx, email)
	if err == nil {
		return user, nil
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		return domain.User{}, err
	}
	id := uuid.NewString()
	user = domain.User{ID: id, Email: email, Status: domain.UserActive}
	parsed, err := uuid.Parse(id)
	if err != nil {
		return domain.User{}, err
	}
	if err := s.queries.CreateUserWithEmail(ctx, sqlcgen.CreateUserWithEmailParams{
		ID:     parsed,
		Email:  email,
		Status: user.Status,
	}); err != nil {
		return domain.User{}, err
	}
	return user, nil
}

// FindByEmail returns the user with email or pgx.ErrNoRows.
func (s *Store) FindByEmail(ctx context.Context, email string) (domain.User, error) {
	return s.findByEmail(ctx, email)
}

func (s *Store) findByEmail(ctx context.Context, email string) (domain.User, error) {
	row, err := s.queries.FindUserByEmail(ctx, email)
	if err != nil {
		return domain.User{}, err
	}
	return domain.User{
		ID:           row.ID,
		Email:        row.Email,
		Mobile:       row.Mobile,
		PasswordHash: row.PasswordHash,
		DisplayName:  row.DisplayName,
		Status:       row.Status,
	}, nil
}

// FindByMobile returns the user with mobile or pgx.ErrNoRows.
func (s *Store) FindByMobile(ctx context.Context, mobile string) (domain.User, error) {
	return s.findByMobile(ctx, mobile)
}

// FindByID returns the user with id or domain.ErrUserNotFound.
func (s *Store) FindByID(ctx context.Context, userID string) (domain.User, error) {
	parsed, err := uuid.Parse(userID)
	if err != nil {
		return domain.User{}, fmt.Errorf("postgres: user id %q: %w", userID, err)
	}
	row, err := s.queries.FindUserByID(ctx, parsed)
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.User{}, domain.ErrUserNotFound
	}
	if err != nil {
		return domain.User{}, err
	}
	return domain.User{
		ID:           row.ID,
		Email:        row.Email,
		Mobile:       row.Mobile,
		PasswordHash: row.PasswordHash,
		DisplayName:  row.DisplayName,
		Status:       row.Status,
	}, nil
}

func (s *Store) findByMobile(ctx context.Context, mobile string) (domain.User, error) {
	row, err := s.queries.FindUserByMobile(ctx, mobile)
	if err != nil {
		return domain.User{}, err
	}
	return domain.User{
		ID:           row.ID,
		Email:        row.Email,
		Mobile:       row.Mobile,
		PasswordHash: row.PasswordHash,
		DisplayName:  row.DisplayName,
		Status:       row.Status,
	}, nil
}

// FindOrCreateByMobile returns the user or creates a user with mobile.
func (s *Store) FindOrCreateByMobile(ctx context.Context, mobile string) (domain.User, error) {
	user, err := s.findByMobile(ctx, mobile)
	if err == nil {
		return user, nil
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		return domain.User{}, err
	}
	id := uuid.NewString()
	parsed, err := uuid.Parse(id)
	if err != nil {
		return domain.User{}, err
	}
	if err := s.queries.CreateUserWithMobile(ctx, sqlcgen.CreateUserWithMobileParams{
		ID:     parsed,
		Mobile: mobile,
	}); err != nil {
		return domain.User{}, err
	}
	return domain.User{ID: id, Mobile: mobile}, nil
}

// UpdateLastLogin records a successful password login.
func (s *Store) UpdateLastLogin(ctx context.Context, userID string) error {
	parsed, err := uuid.Parse(userID)
	if err != nil {
		return fmt.Errorf("postgres: user id %q: %w", userID, err)
	}
	return s.queries.UpdateLastLogin(ctx, parsed)
}

// UpsertDemoUser seeds or updates one demo account.
func (s *Store) UpsertDemoUser(ctx context.Context, email, mobile, passwordHash, displayName string) error {
	var emailPtr, mobilePtr *string
	if email != "" {
		emailPtr = &email
	}
	if mobile != "" {
		mobilePtr = &mobile
	}
	if email == "" {
		return s.queries.UpsertDemoUserByMobile(ctx, sqlcgen.UpsertDemoUserByMobileParams{
			ID:           uuid.New(),
			Email:        emailPtr,
			Mobile:       mobilePtr,
			PasswordHash: passwordHash,
			DisplayName:  displayName,
		})
	}
	return s.queries.UpsertDemoUserByEmail(ctx, sqlcgen.UpsertDemoUserByEmailParams{
		ID:           uuid.New(),
		Email:        emailPtr,
		Mobile:       mobilePtr,
		PasswordHash: passwordHash,
		DisplayName:  displayName,
	})
}

// Store writes one refresh token by hash.
func (s *Store) Store(ctx context.Context, userID, tokenHash string, expiresAt time.Time) error {
	user, err := uuid.Parse(userID)
	if err != nil {
		return fmt.Errorf("postgres: user id %q: %w", userID, err)
	}
	id := uuid.New()
	return s.queries.StoreRefreshToken(ctx, sqlcgen.StoreRefreshTokenParams{
		ID:        id,
		UserID:    user,
		TokenHash: tokenHash,
		ExpiresAt: timestamptz(expiresAt),
	})
}

// FindValid returns the user ID of a live refresh token.
func (s *Store) FindValid(ctx context.Context, tokenHash string) (string, error) {
	return s.queries.FindValidRefreshToken(ctx, tokenHash)
}

// Revoke marks one refresh token revoked.
func (s *Store) Revoke(ctx context.Context, tokenHash string) error {
	return s.queries.RevokeRefreshToken(ctx, tokenHash)
}

// Create writes one API token.
func (s *Store) Create(ctx context.Context, t domain.APIToken) error {
	id, err := uuid.Parse(t.ID)
	if err != nil {
		return fmt.Errorf("postgres: api token id %q: %w", t.ID, err)
	}
	userID, err := uuid.Parse(t.UserID)
	if err != nil {
		return fmt.Errorf("postgres: user id %q: %w", t.UserID, err)
	}
	return s.queries.CreateAPIToken(ctx, sqlcgen.CreateAPITokenParams{
		ID:        id,
		UserID:    userID,
		Name:      t.Name,
		Prefix:    t.Prefix,
		TokenHash: t.TokenHash,
		Scopes:    t.Scopes,
		ExpiresAt: timestamptzPtr(t.ExpiresAt),
	})
}

// ListByUser lists a user's active API tokens.
func (s *Store) ListByUser(ctx context.Context, userID string) ([]domain.APITokenInfo, error) {
	parsed, err := uuid.Parse(userID)
	if err != nil {
		return nil, fmt.Errorf("postgres: user id %q: %w", userID, err)
	}
	rows, err := s.queries.ListAPITokensByUser(ctx, parsed)
	if err != nil {
		return nil, err
	}
	var out []domain.APITokenInfo
	for _, row := range rows {
		out = append(out, domain.APITokenInfo{
			ID:        row.ID,
			Name:      row.Name,
			Prefix:    row.Prefix,
			Scopes:    row.Scopes,
			ExpiresAt: timePtr(row.ExpiresAt),
			CreatedAt: row.CreatedAt.Time,
		})
	}
	return out, nil
}

// RevokeToken revokes one token owned by userID.
func (s *Store) RevokeToken(ctx context.Context, userID, tokenID string) error {
	user, err := uuid.Parse(userID)
	if err != nil {
		return fmt.Errorf("postgres: user id %q: %w", userID, err)
	}
	token, err := uuid.Parse(tokenID)
	if err != nil {
		return fmt.Errorf("postgres: api token id %q: %w", tokenID, err)
	}
	return s.queries.RevokeAPIToken(ctx, sqlcgen.RevokeAPITokenParams{ID: token, UserID: user})
}

// FindByPrefix returns the newest live token with prefix.
func (s *Store) FindByPrefix(ctx context.Context, prefix string) (domain.APIToken, error) {
	row, err := s.queries.FindAPITokenByPrefix(ctx, prefix)
	if err != nil {
		return domain.APIToken{}, err
	}
	return domain.APIToken{
		ID:        row.ID,
		UserID:    row.UserID,
		Name:      row.Name,
		Prefix:    row.Prefix,
		TokenHash: row.TokenHash,
		Scopes:    row.Scopes,
		ExpiresAt: timePtr(row.ExpiresAt),
		RevokedAt: timePtr(row.RevokedAt),
		CreatedAt: row.CreatedAt.Time,
	}, nil
}

func timestamptz(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t, Valid: !t.IsZero()}
}

func timestamptzPtr(t *time.Time) pgtype.Timestamptz {
	if t == nil {
		return pgtype.Timestamptz{}
	}
	return pgtype.Timestamptz{Time: *t, Valid: true}
}

func timePtr(t pgtype.Timestamptz) *time.Time {
	if !t.Valid {
		return nil
	}
	value := t.Time
	return &value
}
